var acceptBloodRequest = async (userId, requestId) => {
  const donor = await prisma.donor.findUnique({
    where: { userId }
  });
  if (!donor || donor.status !== "APPROVED") {
    throw new AppError(
      httpStatus7.FORBIDDEN,
      "Only approved donors can accept blood requests"
    );
  }
  const bloodRequest = await prisma.bloodRequest.findUnique({
    where: { id: requestId }
  });
  if (!bloodRequest) {
    throw new AppError(httpStatus7.NOT_FOUND, "Blood request not found");
  }
  if (bloodRequest.status !== "PENDING") {
    throw new AppError(
      httpStatus7.BAD_REQUEST,
      "This request is already accepted or fulfilled"
    );
  }
  const updatedRequest = await prisma.bloodRequest.update({
    where: { id: requestId },
    data: {
      donorId: donor.id,
      status: "APPROVED"
    }
  });
  return updatedRequest;
};
var updateBloodRequestStatus = async (userId, requestId, payload) => {
  const bloodRequest = await prisma.bloodRequest.findUnique({
    where: { id: requestId }
  });
  if (!bloodRequest) {
    throw new AppError(httpStatus7.NOT_FOUND, "Blood request not found");
  }
  const user = await prisma.user.findUnique({ where: { id: userId } });
  if (bloodRequest.requesterId !== userId && user?.role !== "ADMIN") {
    throw new AppError(
      httpStatus7.FORBIDDEN,
      "You do not have permission to update this request"
    );
  }
  const result = await prisma.bloodRequest.update({
    where: { id: requestId },
    data: payload
  });
  return result;
};
