// src/app/lib/bkash.ts
var getBkashIdToken = async () => {
  try {
    const IdTokenKey = "bkash:idToken";
    const RefreshTokenKey = "bkash:refreshToken";
    let bkashIdToken = await redisClient.get(IdTokenKey);
    const bkashIdTokenTTL = await redisClient.ttl(IdTokenKey);
    const bkashRefreshToken = await redisClient.get(RefreshTokenKey);
    const bkashRefreshTokenTTL = await redisClient.ttl(RefreshTokenKey);
    if (bkashIdTokenTTL <= 600 && bkashRefreshToken && bkashRefreshTokenTTL > 600) {
      const refreshTokenResponse = await fetch(
        `${config_default.bkash_base_url}/tokenized/checkout/token/refresh`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
            username: config_default.bkash_username,
            password: config_default.bkash_password
          },
          body: JSON.stringify({
            app_key: config_default.bkash_app_key,
            app_secret: config_default.bkash_app_secret,
            refresh_token: bkashRefreshToken
          })
        }
      );
      const bkashRefreshTokenResult = await refreshTokenResponse.json();
      bkashIdToken = bkashRefreshTokenResult.id_token;
      await redisClient.set(IdTokenKey, bkashRefreshTokenResult.id_token, {
        expiration: {
          type: "EX",
          value: 60 * 60
        }
      });
      return bkashIdToken;
    }
    if (bkashIdToken) {
      return bkashIdToken;
    }
    const response = await fetch(
      `${config_default.bkash_base_url}/tokenized/checkout/token/grant`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
          username: config_default.bkash_username,
          password: config_default.bkash_password
        },
        body: JSON.stringify({
          app_key: config_default.bkash_app_key,
          app_secret: config_default.bkash_app_secret
        })
      }
    );
    if (!response.ok) {
      throw new Error("Bkash id token Grant failed");
    }
    const result = await response.json();
    await redisClient.set(IdTokenKey, result.id_token, {
      expiration: {
        type: "EX",
        value: 60 * 60
      }
    });
    await redisClient.set(RefreshTokenKey, result.refresh_token, {
      expiration: {
        type: "EX",
        value: 60 * 60 * 24 * 28
      }
    });
    bkashIdToken = result.id_token;
    return bkashIdToken;
  } catch (error) {
    throw new Error(error.message);
  }
};

// src/app/module/payment/payment.service.ts
var createPayment = async (payload, user) => {
  return await prisma.$transaction(async (tx) => {
    const bkashIdToken = await getBkashIdToken();
    if (!bkashIdToken) {
      throw new Error("No bkash access token found");
    }
    const payerRef = payload.payerReference || user.email;
    const amountStr = payload.amount ? String(payload.amount) : "0";
    const initialPayment = await tx.payment.create({
      data: {
        userId: user.id,
        bloodRequestId: payload.bloodRequestId || null,
        amount: new prismaNamespace_exports.Decimal(amountStr),
        status: PaymentStatus.PENDING,
        payerReference: payerRef,
        merchantInvoiceNumber: `INV-${Date.now()}-${Math.floor(
          Math.random() * 1e3
        )}`
      }
    });
    const bkashCreatePaymentResponse = await fetch(
      `${config_default.bkash_base_url}/tokenized/checkout/create`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
          Authorization: bkashIdToken,
          "X-App-Key": config_default.bkash_app_key
        },
        body: JSON.stringify({
          mode: "0011",
          payerReference: payerRef,
          callbackURL: `${config_default.bkash_callback_url}/payments/bkash/callback`,
          amount: amountStr,
          currency: "BDT",
          intent: "sale",
          merchantInvoiceNumber: initialPayment.merchantInvoiceNumber
        })
      }
    );
    const bkashCreatePaymentResult = await bkashCreatePaymentResponse.json();
    const updatedPayment = await tx.payment.update({
      where: { id: initialPayment.id },
      data: {
        bkashPaymentId: bkashCreatePaymentResult.paymentID || null
      }
    });
    return {
      paymentUrl: bkashCreatePaymentResult.bkashURL,
      payment: updatedPayment
    };
  });
};
var payPayment = async (payload, user) => {
  if (!payload.paymentId) {
    throw new Error("Payment ID is required.");
  }
  const existingPayment = await prisma.payment.findUnique({
    where: { id: payload.paymentId }
  });
  if (!existingPayment) {
    throw new Error("Payment record not found.");
  }
  const bkashIdToken = await getBkashIdToken();
  if (!bkashIdToken) {
    throw new Error("No bkash access token found");
  }
  const payerRef = payload.payerReference || existingPayment.payerReference || user.email;
  let amountStr = "0";
  if (payload.amount) {
    amountStr = String(payload.amount);
  } else if (existingPayment.amount) {
    amountStr = existingPayment.amount.toString();
  }
  if (Number(amountStr) <= 0) {
    throw new Error("Invalid payment amount. Amount must be greater than 0.");
  }
  const bkashCreatePaymentResponse = await fetch(
    `${config_default.bkash_base_url}/tokenized/checkout/create`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: bkashIdToken,
        "X-App-Key": config_default.bkash_app_key
      },
      body: JSON.stringify({
        mode: "0011",
        payerReference: payerRef,
        callbackURL: `${config_default.bkash_callback_url}/payments/bkash/callback`,
        amount: amountStr,
        currency: "BDT",
        intent: "sale",
        merchantInvoiceNumber: existingPayment.merchantInvoiceNumber
      })
    }
  );
  const bkashCreatePaymentResult = await bkashCreatePaymentResponse.json();
  const updatedPayment = await prisma.payment.update({
    where: { id: existingPayment.id },
    data: {
      bkashPaymentId: bkashCreatePaymentResult.paymentID || null,
      status: PaymentStatus.PENDING
    }
  });
  return {
    paymentUrl: bkashCreatePaymentResult.bkashURL,
    payment: updatedPayment
  };
};
var bkashCallback = async (query) => {
  const paymentId = query.paymentID;
  const status = query.status;
  if (!paymentId) throw new Error("PaymentID is missing");
  if (!status) throw new Error("Status is missing");
  const frontendUrl = config_default.frontend_url || "http://localhost:3000";
  if (status === "success") {
    const bkashIdToken = await getBkashIdToken();
    if (!bkashIdToken) {
      throw new Error("No bkash access token found");
    }
    const executedPaymentResponse = await fetch(
      `${config_default.bkash_base_url}/tokenized/checkout/execute`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
          Authorization: bkashIdToken,
          "X-App-Key": config_default.bkash_app_key
        },
        body: JSON.stringify({ paymentID: paymentId })
      }
    );
    const executedPaymentResult = await executedPaymentResponse.json();
    const updatedPayment = await prisma.payment.update({
      where: { bkashPaymentId: paymentId },
      data: {
        status: PaymentStatus.PAID,
        bkashTrxId: executedPaymentResult.trxID,
        paidAt: executedPaymentResult.paymentExecuteTime || (/* @__PURE__ */ new Date()).toISOString()
      }
    });
    return {
      redirectUrl: `${frontendUrl}/payment/success?transactionId=${updatedPayment.bkashTrxId}&paymentId=${updatedPayment.id}`
    };
  } else if (status === "failure") {
    const updatedPayment = await prisma.payment.update({
      where: { bkashPaymentId: paymentId },
      data: {
        status: PaymentStatus.FAILED
      }
    });
    return {
      redirectUrl: `${frontendUrl}/payment/failed?paymentId=${updatedPayment.id}`
    };
  } else if (status === "cancel") {
    const updatedPayment = await prisma.payment.update({
      where: { bkashPaymentId: paymentId },
      data: {
        status: PaymentStatus.CANCELLED
      }
    });
    return {
      redirectUrl: `${frontendUrl}/payment/cancel?paymentId=${updatedPayment.id}`
    };
  } else {
    throw new Error("Invalid payment status received");
  }
};
var getMyPayments = async (user) => {
  return await prisma.payment.findMany({
    where: { userId: user.id },
    include: {
      bloodRequest: true
    },
    orderBy: { createdAt: "desc" }
  });
};
var PaymentServices = {
  createPayment,
  payPayment,
  bkashCallback,
  getMyPayments
};

