// src/app/module/review/review.service.ts
var createReview = async (payload, user) => {
  const donor = await prisma.donor.findUnique({
    where: { id: payload.donorId }
  });
  if (!donor) {
    throw new Error("Donor not found");
  }
  if (donor.id === user.id) {
    throw new Error("You cannot review yourself");
  }
  const review = await prisma.review.create({
    data: {
      userId: user.id,
      donorId: payload.donorId,
      rating: payload.rating,
      comment: payload.comment || null
    },
    include: {
      user: {
        select: {
          id: true,
          name: true,
          email: true
        }
      },
      donor: true
    }
  });
  return review;
};
var getAllReviews = async () => {
  return await prisma.review.findMany({
    include: {
      user: {
        select: {
          id: true,
          name: true,
          email: true
        }
      },
      donor: true
    },
    orderBy: { createdAt: "desc" }
  });
};
var getDonorReviews = async (donorId) => {
  return await prisma.review.findMany({
    where: { donorId },
    include: {
      user: {
        select: {
          id: true,
          name: true
        }
      }
    },
    orderBy: { createdAt: "desc" }
  });
};
var ReviewServices = {
  createReview,
  getAllReviews,
  getDonorReviews
};

