// src/app/utils/seed.ts
import bcrypt2 from "bcryptjs";
var seedTesterAdmin = async () => {
  try {
    const isTesterAdminExists = await prisma.user.findUnique({
      where: {
        email: config_default.tester_admin_email
      }
    });
    if (isTesterAdminExists) {
      console.log("Tester Admin already exists.");
      return;
    }
    const name = config_default.tester_admin_name;
    const email = config_default.tester_admin_email;
    const password = config_default.tester_admin_password;
    if (!name || !email || !password) {
      throw new Error(
        "Tester Admin Name, Email, Password Missing env file!!!!"
      );
    }
    const hashPassword = await bcrypt2.hash(
      password,
      Number(config_default.bcrypt_salt_rounds)
    );
    const testerAdmin = await prisma.user.create({
      data: {
        name,
        email,
        password: hashPassword,
        role: Role.ADMIN,
        needPasswordChange: false,
        emailVerified: true
      }
    });
    console.log("Tester Admin created: ", testerAdmin);
  } catch (error) {
    console.log("Error seeding tester admin: ", error);
    await prisma.user.delete({
      where: {
        email: config_default.tester_admin_email
      }
    });
  }
};

// src/vercel.ts
var ready = null;
function init() {
  if (!ready) {
    ready = (async () => {
      await prisma.$connect();
      if (!redisClient.isOpen) await redisClient.connect();
      await seedTesterAdmin();
    })().catch((err) => {
      ready = null;
      throw err;
    });
  }
  return ready;
}
async function handler(req, res) {
  await init();
  return app_default(req, res);
}
export {
  handler as default
};
